// The helpers that every backend shares (docs/spec/fsm.md, B-6): the name of the shared module, the pascal notation of a key, the
// text of a list of lines and the header of a generated file in a language whose comments start with two slashes.

/** The key of the module that holds what the machines share: the error codes and the Error. */
export const SHARED = 'fsm';

/** The name of a key in the pascal notation of B-6. Keys match ^[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*$, so this is one-to-one. */
export const pascal = key => key.split('_').map(word => word[0].toUpperCase() + word.slice(1)).join('');

/** The text of a list of lines: each line ends with a line break. */
export const text = lines => `${lines.join('\n')}\n`;

/** The first line of a generated file whose comments start with two slashes (docs/spec/fsm.md, B-6). */
export const header = from => `// Code generated by fsm-gen from ${from}; DO NOT EDIT.`;
